#!/bin/bash
# Print the software/hardware stack of both containers used by the cricket pipeline (for documentation).
R=/lustre/fsw/general_sa/bbalakreshna/clustercodes
M="--container-mounts=/lustre:/lustre --no-container-remap-root --ntasks=1"
echo "### host"; nvidia-smi --query-gpu=index,name,memory.total,driver_version,compute_cap --format=csv; nvidia-smi | grep -m1 "CUDA Version"; uname -r; lscpu | grep -E "Model name|Architecture|^CPU\(s\)"; free -g | head -2
echo "### pytorch container"; srun $M --container-image=$R/containers/pytorch-main-py3-devel.sqsh bash -c "source $R/venv/qwen38-ft/bin/activate; python -V; nvcc --version | tail -2; python -c 'import torch,transformers,peft,accelerate,wandb,fla,triton,huggingface_hub;print(\"torch\",torch.__version__,\"cuda\",torch.version.cuda,\"| transformers\",transformers.__version__,\"| peft\",peft.__version__,\"| accelerate\",accelerate.__version__,\"| wandb\",wandb.__version__,\"| fla\",fla.__version__,\"| triton\",triton.__version__,\"| hf_hub\",huggingface_hub.__version__, \"| nccl\", torch.cuda.nccl.version())' 2>&1 | grep -v Warning | tail -1; cat /etc/os-release | grep PRETTY"
echo "### vllm container"; srun $M --container-image=$R/containers/vllm-rubin-py3-devel.sqsh bash -c "python3 -V; nvcc --version 2>/dev/null | tail -2; python3 -c 'import torch,vllm,transformers,triton;print(\"torch\",torch.__version__,\"cuda\",torch.version.cuda,\"| vllm\",vllm.__version__,\"| transformers\",transformers.__version__,\"| triton\",triton.__version__)' 2>&1 | grep -v -i warn | tail -1; cat /etc/os-release | grep PRETTY"
